@@ -50,0 +50,16 @@
+  static void scaleGatherScatterIndex(C2_MacroAssembler* masm, VectorRegister dst,
+                                      VectorRegister idx, BasicType bt, uint vector_length) {
+    Assembler::SEW sew = Assembler::elemtype_to_sew(bt);
+    if (UseZvbb) {
+      // e32,mf2 and e64,m1 have the same VLMAX, so the following
+      // memory access observes the same vl.
+      __ vsetvli_helper(T_INT, vector_length, Assembler::mf2);
+      __ vwsll_vi(dst, idx, (int)sew);
+      __ vsetvli_helper(bt, vector_length);
+    } else {
+      __ vsetvli_helper(bt, vector_length);
+      __ vzext_vf2(dst, idx);
+      __ vsll_vi(dst, dst, (int)sew);
+    }
+  }
